// The workflows you expect to run, and how long each may go without a successful run.
// Find a workflow's ID in its URL: /workflow/<ID>
return [
  { workflowId: 'REPLACE_WITH_WORKFLOW_ID', name: 'Website form → CRM', maxHoursQuiet: 24 },
  { workflowId: 'REPLACE_WITH_WORKFLOW_ID', name: 'Nightly invoice sync', maxHoursQuiet: 26 },
].map(w => ({ json: w }));

// Compares each workflow's last successful run with its allowed quiet time.
// Returns nothing (so no alert is sent) when everything ran.
const watch = $('Workflows to watch').all();
const now = Date.now();
const quiet = [];
$input.all().forEach((r, i) => {
  const w = watch[i].json;
  const last = (r.json.data || [])[0];
  const when = last && (last.stoppedAt || last.startedAt);
  const hours = when ? (now - new Date(when).getTime()) / 36e5 : Infinity;
  if (hours > w.maxHoursQuiet) quiet.push({ ...w, lastSuccess: when || null, hoursQuiet: when ? Math.round(hours) : null });
});
if (!quiet.length) return [];
const lines = quiet.map(q => `• ${q.name}: ${q.lastSuccess ? `last successful run ${q.hoursQuiet} hours ago` : 'no successful run in the saved history'} (expected within ${q.maxHoursQuiet}h)`);
return [{ json: { text: `🔕 ${quiet.length} workflow${quiet.length > 1 ? 's have' : ' has'} gone quiet\n` + lines.join('\n'), quiet } }];
